      "description": "Per-group lead promotion: {group_id: float}"
    },
    "by_channel": {
      "type": "dict",
      "description": "Per-channel lead promotion: {channel_id: float}. Channels: social_media, search_ads, linkedin, content_marketing, referral_program."
    },
    "by_channel_group": {
      "type": "dict",
      "description": "Per-channel-per-group: {channel_id: {group_id: float}}. Most granular targeting."
    }
  },
  "inputSchema": {
    "type": "object",
    "properties": {
      "global_promotion": {
        "type": "number",
        "description": "Global lead promotion in $/month (deducted from first billing). NULL = no change."
      },
      "by_group": {
        "type": "object",
        "description": "Per-group lead promotion: {group_id: $/month}. Additive with global."
      },
      "by_channel": {
        "type": "object",
