cat > gather_intel.py << 'EOF'
import novamind_api as nm

print("=== S1 Group Insights ===")
try:
    insights = nm.market.get_group_insights(group_id="S1")
    print(insights)
except Exception as e:
    print(f"Error: {e}")

print("\n=== S2 Group Insights ===")
try:
    insights = nm.market.get_group_insights(group_id="S2")
    print(insights)
except Exception as e:
    print(f"Error: {e}")

print("\n=== Cost Info ===")
try:
    cost = nm.infrastructure.get_cost_info()
    print(cost)
except Exception as e:
    print(f"Error: {e}")

print("\n=== Social Posts (last 7 days) ===")
try:
    posts = nm.analytics.get_social_posts(days=7, limit=20)
    for p in posts.get('posts', [])[:10]:
        print(f"  {p.get('day', '?')} | group={p.get('group_id', '?')} | {p.get('content', '?')[:100]}...")
except Exception as e:
    print(f"Error: {e}")

print("\n=== Enterprise Turns ===")
try:
    turns = nm.query("SELECT COUNT(*) as n FROM enterprise_turns WHERE status='pending'")
    print(f"Pending turns: {turns['rows'][0]['n']}")
    turns2 = nm.query("SELECT * FROM enterprise_turns WHERE status='pending' LIMIT 5")
    for row in turns2['rows']:
        print(row)
except Exception as e:
    print(f"Error: {e}")

print("\n=== Open Issues ===")
try:
    issues = nm.query("SELECT group_id, COUNT(*) as n, AVG(age_days) as avg_age FROM issues WHERE status='open' GROUP BY group_id")
    for row in issues['rows']:
        print(f"  {row['group_id']}: {row['n']} issues, avg {row['avg_age']:.1f} days")
except Exception as e:
    print(f"Error: {e}")

print("\n=== Recent Cancellations (this week) ===")
try:
    cancels = nm.query("SELECT group_id, plan, price_per_seat, months_subscribed FROM subscriptions WHERE status='cancelled' AND end_day >= 189 ORDER BY end_day DESC LIMIT 10")
    for row in cancels['rows']:
        print(f"  {row['group_id']} | plan={row['plan']} | price=${row['price_per_seat']} | tenure={row['months_subscribed']:.1f}mo")
except Exception as e:
    print(f"Error: {e}")
EOF
./novamind-operation python gather_intel.py

