    print(f'Pending enterprise turns: {r[\"rows\"][0][\"n\"]}')
except Exception as e:
    print(f'Error: {e}')

# Check for any daily costs beyond capacity tier
try:
    ledger = nm.query('SELECT description, SUM(amount) as total FROM ledger WHERE day >= 300 GROUP BY description ORDER BY total')
    for row in ledger['rows']:
        print(row)
except Exception as e:
    print(f'Ledger error: {e}')
"

